INSERT INTO `email_templates` (`id`, `name`, `action`, `subject`, `body`, `type`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Order Invoice', 'admin.invoice_issued', 'Invoice {{invoice_number}} for order {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#0f766e 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">Central Billing</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">Invoice issued and ready</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">Marketplace invoice emails with order, payment, and store details.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Invoice Number</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{invoice_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Order Number</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Store</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{store_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Amount Paid</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{amount}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Payment Method</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{payment_method}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Issued At</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{issued_at}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">Key details included in this template:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">Customer: {{customer_name}}</li><li style=\"margin:0 0 10px 0;\">Customer email: {{customer_email}}</li><li style=\"margin:0 0 10px 0;\">Payment reference: {{payment_reference}}</li><li style=\"margin:0 0 10px 0;\">Support email: {{support_email}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{portal_url}}/admin/wallet/invoices\" style=\"display:inline-block;background:#0f766e;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">Open billing</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">This email was generated by {{app_name}}. If you need help, contact {{support_email}} or visit {{portal_url}}. Copyright {{current_year}} {{app_name}}.</div></td></tr></table></td></tr></table></div>', 'admin', 'active', '2026-06-12 09:48:11', '2026-06-12 09:48:11'),
(2, 'Admin Order Alert', 'admin.order_alert', 'Order {{order_number}} requires central review', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#1d4ed8 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">Central Orders</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">Order lifecycle alert</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">Use for payment review, fulfillment intervention, or operational escalations.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Order Number</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Store</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{store_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Customer</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{customer_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Order Status</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Shipping Status</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Order Total</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_total}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">Key details included in this template:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">Placed at: {{placed_at}}</li><li style=\"margin:0 0 10px 0;\">Payment method: {{payment_method}}</li><li style=\"margin:0 0 10px 0;\">Action summary: {{action_summary}}</li><li style=\"margin:0 0 10px 0;\">Admin note: {{admin_note}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{portal_url}}/admin/orders\" style=\"display:inline-block;background:#1d4ed8;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">Open orders</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">This email was generated by {{app_name}}. If you need help, contact {{support_email}} or visit {{portal_url}}. Copyright {{current_year}} {{app_name}}.</div></td></tr></table></td></tr></table></div>', 'admin', 'active', '2026-06-12 09:48:11', '2026-06-12 09:48:11'),
(3, 'Shipping Escalation Notice', 'admin.shipping_escalation', 'Shipping escalation for order {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#b45309 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">Central Shipping</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">Shipping issue needs attention</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">Use for delayed delivery, carrier exception, or handoff problems.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Order Number</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Carrier</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{carrier_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Tracking Number</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{tracking_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Shipping Status</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Estimated Delivery</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{estimated_delivery}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">Destination</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_address}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">Key details included in this template:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">Tracking URL: {{tracking_url}}</li><li style=\"margin:0 0 10px 0;\">Escalation reason: {{escalation_reason}}</li><li style=\"margin:0 0 10px 0;\">Assigned team: {{assigned_team}}</li><li style=\"margin:0 0 10px 0;\">Store: {{store_name}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{portal_url}}/admin/orders\" style=\"display:inline-block;background:#b45309;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">Open shipping queue</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">This email was generated by {{app_name}}. If you need help, c