(72, 9, 'ar', 'طلبك {{order_number}} قيد التحضير الآن', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#1d4ed8 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">طلبات المتجر</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">الطلب قيد التنفيذ</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">يستخدم عندما ينتقل الطلب إلى المعالجة بعد تأكيد الدفع.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">رقم الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">العميل</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{customer_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">حالة الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">حالة الشحن</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">إجمالي الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_total}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">التسليم المتوقع</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{estimated_delivery}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">التفاصيل الرئيسية المدرجة في هذا القالب:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">مرجع الدفع: {{payment_reference}}</li><li style=\"margin:0 0 10px 0;\">الفريق المعين: {{assigned_team}}</li><li style=\"margin:0 0 10px 0;\">ملاحظة المتجر: {{action_summary}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{portal_url}}/orders/{{order_number}}\" style=\"display:inline-block;background:#1d4ed8;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">التحقق من التقدم</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">تم إنشاء هذا البريد الإلكتروني بواسطة {{app_name}}. إذا كنت بحاجة إلى مساعدة، اتصل بـ {{support_email}} أو زر {{portal_url}}. حقوق النشر © {{current_year}} {{app_name}}.</div></td></tr></table></td></tr></table></div>', '2026-07-14 14:25:22', '2026-07-14 14:25:22'),
(73, 10, 'ar', 'تحديث الشحن للطلب {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#b45309 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">شحن المتجر</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">شحنتك في الطريق</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">يستخدم للإرسال، أثناء النقل، تأخير التسليم، وتحديثات التتبع.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">رقم الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">الناقل</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{carrier_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">رقم التتبع</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{tracking_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">حالة الشحن</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">التسليم المتوقع</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{estimated_delivery}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">الوجهة</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{shipping_address}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">التفاصيل الرئيسية المدرجة في هذا القالب:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">رابط التتبع: {{tracking_url}}</li><li style=\"margin:0 0 10px 0;\">حالة الطلب: {{order_status}}</li><li style=\"margin:0 0 10px 0;\">البريد الإلكتروني للدعم: {{support_email}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{tracking_url}}\" style=\"display:inline-block;background:#b45309;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">تتبع الشحنة</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">تم إنشاء هذا البريد الإلكتروني بواسطة {{app_name}}. إذا كنت بحاجة إلى مساعدة، اتصل بـ {{support_email}} أو زر {{portal_url}}. حقوق النشر © {{current_year}} {{app_name}}.</div></td></tr></table></td></tr></table></div>', '2026-07-14 14:25:22', '2026-07-14 14:25:22'),
(74, 11, 'ar', 'تم تسليم الطلب {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#0f766e 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">شحن المتجر</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">اكتمل التسليم</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">يستخدم عندما يتم وضع علامة على الطلب كمُسلَّم ويجب أن يتلقى العميل تأكيدًا نهائيًا.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">رقم الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">تم التسليم إلى</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{customer_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">تم التسليم في</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{processed_at}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">الناقل</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{carrier_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">رقم التتبع</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{tracking_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">إجمالي الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_total}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">التفاصيل الرئيسية المدرجة في هذا القالب:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">عنوان التسليم: {{shipping_address}}</li><li style=\"margin:0 0 10px 0;\">هل تحتاج إلى مساعدة؟ اتصل بـ {{support_email}}</li><li style=\"margin:0 0 10px 0;\">راجع تفاصيل الطلب على {{portal_url}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{portal_url}}/orders/{{order_number}}\" style=\"display:inline-block;background:#0f766e;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">مراجعة الطلب</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">تم إنشاء هذا البريد الإلكتروني بواسطة {{app_name}}. إذا كنت بحاجة إلى مساعدة، اتصل بـ {{support_email}} أو زر {{portal_url}}. حقوق النشر © {{current_year}} {{app_name}}.</div></td></tr></table></td></tr></table></div>', '2026-07-14 14:25:22', '2026-07-14 14:32:03'),
(75, 12, 'ar', 'تم إلغاء الطلب {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#be123c 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">طلبات المتجر</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">تم إلغاء الطلب</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">يستخدم لإلغاءات بناءً على طلب العميل، مشاكل المخزون، أو فشل الدفع.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">رقم الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">العميل</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{customer_name}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">تم الإلغاء في</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{processed_at}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">الحالة</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">حالة الاسترداد</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{transaction_status}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">إجمالي الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_total}}</td></tr></table></td></tr><tr><td style=\"padding:8px 40px 8px 40px;\"><div style=\"font-size:14px;line-height:1.8;color:#374151;\"><p style=\"margin:0 0 14px 0;\">التفاصيل الرئيسية المدرجة في هذا القالب:</p><ul style=\"padding-left:18px;margin:0;font-size:14px;line-height:1.7;color:#374151;\"><li style=\"margin:0 0 10px 0;\">السبب: {{cancellation_reason}}</li><li style=\"margin:0 0 10px 0;\">طريقة الدفع: {{payment_method}}</li><li style=\"margin:0 0 10px 0;\">البريد الإلكتروني للدعم: {{support_email}}</li></ul></div></td></tr><tr><td style=\"padding:24px 40px 22px 40px;\"><a href=\"{{portal_url}}/contact\" style=\"display:inline-block;background:#be123c;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:14px 22px;border-radius:999px;\">اتصل بالدعم</a></td></tr><tr><td style=\"padding:0 40px 34px 40px;\"><div style=\"padding-top:18px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.8;color:#6b7280;\">تم إنشاء هذا البريد الإلكتروني بواسطة {{app_name}}. إذا كنت بحاجة إلى مساعدة، اتصل بـ {{support_email}} أو زر {{portal_url}}. حقوق النشر © {{current_year}} {{app_name}}.</div></td></tr></table></td></tr></table></div>', '2026-07-14 14:25:22', '2026-07-14 14:25:22'),
(76, 13, 'ar', 'تم استلام الدفع للطلب {{order_number}}', '<div style=\"margin:0;padding:0;background:#eef2f7;font-family:Arial,Helvetica,sans-serif;color:#111827;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:28px 0;\"><tr><td align=\"center\"><table role=\"presentation\" width=\"680\" cellspacing=\"0\" cellpadding=\"0\" style=\"width:680px;max-width:680px;background:#ffffff;border-radius:20px;overflow:hidden;box-shadow:0 18px 40px rgba(15,23,42,0.12);\"><tr><td style=\"padding:0;background:linear-gradient(135deg,#1d4ed8 0%, #111827 100%);\"><div style=\"padding:34px 40px 28px 40px;\"><div style=\"font-size:11px;letter-spacing:0.18em;text-transform:uppercase;color:rgba(255,255,255,0.78);font-weight:700;\">مدفوعات المتجر</div><h1 style=\"margin:14px 0 12px 0;font-size:30px;line-height:1.2;color:#ffffff;font-weight:700;\">تم استلام الدفع بنجاح</h1><p style=\"margin:0;font-size:15px;line-height:1.7;color:rgba(255,255,255,0.88);\">استخدم بعد التقاط الدفع بنجاح لتأكيد سجل الفوترة للطلب.</p></div></td></tr><tr><td style=\"padding:30px 40px 18px 40px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"border:1px solid #e5e7eb;border-radius:16px;background:#f8fafc;padding:0 24px;\"><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">رقم الطلب</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{order_number}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">المبلغ المستلم</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:600;\">{{transaction_amount}}</td></tr><tr><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;width:38%;\">طريقة الدفع</td><td style=\"padding:10px 0;border-bottom:1px solid #e5e7eb;fo